.com/vercel/next.js/compare/v16.3.3...v16.3.4)\n\n---\nupdated-dependencies:\n- dependency-name: next\n  dependency-version: 16.3.4\n  dependency-type: direct:production\n  update-type: version-update:semver-patch\n  dependency-group: npm-minor-patch\n...\n\nSigned-off-by: dependabot[bot] <support@github.com>","tree":{"sha":"37c1afff8915d873bd98983f9031e6e95e192f0c","url":"https://api.github.com/repos/portable-genai/account-takeover-investigator/git/trees/37c1afff8915d873bd98983f9031e6e95e192f0c"},"url":"https://api.github.com/repos/portable-genai/account-takeover-investigator/git/commits/ada8a420452c86c44cdb6750b76283f72d1bc107","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/72717?v=4","events_url":"https://api.github.com/users/ashishawasthi/events{/privacy}","followers_url":"https://api.github.com/users/ashishawasthi/followers","following_url":"https://api.github.com/users/ashishawasthi/following{/other_user}","gists_url":"https://api.github.com/users/ashishawasthi/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/ashishawasthi","id":72717,"login":"ashishawasthi","node_id":"MDQ6VXNlcjcyNzE3","organizations_url":"https://api.github.com/users/ashishawasthi/orgs","received_events_url":"https://api.github.com/users/ashishawasthi/received_events","repos_url":"https://api.github.com/users/ashishawasthi/repos","site_admin":false,"starred_url":"https://api.github.com/users/ashishawasthi/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/ashishawasthi/subscriptions","type":"User","url":"https://api.github.com/users/ashishawasthi","user_view_type":"public"},"html_url":"https://github.com/portable-genai/account-takeover-investigator/commit/ada8a420452c86c44cdb6750b76283f72d1bc107","node_id":"C_kwDOUAh5LtoAKGFkYThhNDIwNDUyYzg2YzQ0Y2RiNjc1MGI3NjI4M2Y3MmQxYmMxMDc","parents":[{"html_url":"https://github.com/portable-g